import {libraryIcon} from './agent-appearance.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(action,label,attrs='')=>`<button type="button" data-work="${action}" ${attrs}>${label}</button>`;
const dateLabel=date=>new Date(date+'T12:00:00Z').toLocaleDateString([],{timeZone:'UTC',month:'short',day:'numeric'});
const dateKey=(date)=>date.toISOString().slice(0,10);
const todayIn=zone=>new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const iconFor=kind=>({plan:'list-tree',task:'clipboard-list',milestone:'flag',sprint:'rotate-ccw'})[kind]||'calendar';

function parts(value,zone){
  if(!value)return ['',''];
  if(value.startsWith('T'))return ['',value.slice(1)];
  if(!/(Z|[+-]\d{2}:\d{2})$/.test(value))return [value.slice(0,10),value.slice(11)];
  const fields=new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(new Date(value));
  const d=Object.fromEntries(fields.map(f=>[f.type,f.value]));return [`${d.year}-${d.month}-${d.day}`,`${d.hour}:${d.minute}:${d.second}`];
}
export function dateFields(schedule={},zone='UTC',{milestone=true}={}){
  return `<fieldset class="schedule-dates"><legend>${libraryIcon('calendar',16)} Dates <small>optional</small></legend><p class="schedule-note">${esc(zone)} · Leave time empty for an all-day date. Deadlines end at the close of that day.</p><div class="schedule-date-grid">${[['start','Start'],['due','Deadline']].map(([key,label])=>{const [date,time]=parts(schedule?.[key],zone);return `<div><label><span class="schedule-field-label">${label}</span><input type="date" name="schedule${key}Date" value="${date}" data-original="${esc(schedule?.[key]||'')}" data-date="${date}" data-time="${time}"></label><label><span class="schedule-field-label">${label} time <small>optional</small></span><input type="time" step="1" name="schedule${key}Time" value="${time}"></label></div>`;}).join('')}</div>${milestone?`<label class="schedule-check"><input type="checkbox" name="scheduleMilestone" ${schedule?.milestone?'checked':''}>Show as a milestone</label>`:''}</fieldset>`;
}
export function readDates(form,{validate=true}={}){
  const result={};for(const key of ['start','due']){const date=form.elements['schedule'+key+'Date'],time=form.elements['schedule'+key+'Time'];if(!date)continue;if(validate&&time.value&&!date.value)throw Error('Choose a date for the '+(key==='due'?'deadline':'start')+' time.');result[key]=date.value===date.dataset.date&&time.value===date.dataset.time?date.dataset.original||null:date.value+(time.value?'T'+time.value:'')||null;}
  if(form.elements.scheduleMilestone)result.milestone=form.elements.scheduleMilestone.checked;return result;
}
export function reminderFields(settings,{project=false,inherit=false,overrides=null}={}){
  const p=overrides||settings;
  return `<fieldset class="schedule-rules"><legend>${libraryIcon('bell',16)} Reminders</legend>${inherit?`<label>Reminder rules<select name="reminderMode"><option value="inherit" ${!overrides?'selected':''}>Use project settings</option><option value="custom" ${overrides?'selected':''}>Customize for this plan</option></select></label><p class="schedule-note">Task deadlines and sprint windows use this plan’s rules. Project timezone and permission to resume inactive agents stay under project settings.</p>`:''}<fieldset class="schedule-custom" ${inherit&&!overrides?'hidden disabled':''}>${project?`<label>Project time zone<input name="scheduleZone" value="${esc(p.timeZone)}" list="schedule-zones" required placeholder="America/Los_Angeles"></label><datalist id="schedule-zones">${[...new Set([p.timeZone,'UTC',...Intl.supportedValuesOf('timeZone')])].map(zone=>`<option value="${esc(zone)}"></option>`).join('')}</datalist><p class="schedule-note">Local dates follow this zone. Changing it moves existing local deadlines; dates with an explicit offset stay fixed.</p>`:''}<label class="schedule-check"><input type="checkbox" name="scheduleEnabled" ${p.enabled?'checked':''}>Enable saved reminders</label><div class="schedule-rule-grid"><label>Before a deadline <small>minutes · 0 to skip</small><input type="number" min="0" max="43200" name="scheduleLead" value="${p.leadMinutes}" required></label><label>Minimum reminder gap <small>minutes per plan</small><input type="number" min="15" max="10080" name="scheduleCooldown" value="${p.cooldownMinutes}" required></label></div><label class="schedule-check"><input type="checkbox" name="scheduleOverdue" ${p.overdue?'checked':''}>Remind me when work becomes overdue</label><div class="schedule-rule-grid"><label>Recurring progress check-in <small>minutes · 0 to turn off, otherwise 15+</small><input type="number" min="0" max="10080" name="scheduleCheckIn" value="${p.checkInMinutes}" required></label><label>Also notify agents<select name="scheduleTarget">${[['none','Notifications for me only'],['owner','Owners of unfinished tasks'],['coordinator','Scrum Master / coordinator']].map(([id,label])=>`<option value="${id}" ${id===p.agentTarget?'selected':''}>${label}</option>`).join('')}</select></label></div><p class="schedule-note">The coordinator is the assigned process lead, or the orchestrator when there is no process lead. Unassigned roles leave the reminder with you. Agents follow your normal task approval policy.</p><label class="schedule-check"><input type="checkbox" name="scheduleQuiet" ${p.quietHours.enabled?'checked':''}>Quiet hours · hold alerts and agent check-ins</label><div class="schedule-rule-grid"><label>From<input type="time" name="scheduleQuietStart" value="${p.quietHours.start}" required></label><label>Until<input type="time" name="scheduleQuietEnd" value="${p.quietHours.end}" required></label></div>${project?`<label class="schedule-check"><input type="checkbox" name="scheduleResume" ${p.resumeInactive?'checked':''}><span>Allow reminders to resume inactive agents<small>Only verified, saved sessions in this project. May use your provider credits. Busy agents always wait.</small></span></label>`:''}</fieldset></fieldset>`;
}
export function syncScheduleFields(form){const mode=form?.elements?.reminderMode,custom=form?.querySelector('.schedule-custom');if(mode&&custom){custom.hidden=mode.value==='inherit';custom.disabled=custom.hidden;}}
export function readReminders(form,{project=false}={}){
  if(form.elements.reminderMode?.value==='inherit')return null;
  const f=form.elements;
  return {enabled:f.scheduleEnabled.checked,leadMinutes:Number(f.scheduleLead.value),overdue:f.scheduleOverdue.checked,checkInMinutes:Number(f.scheduleCheckIn.value),agentTarget:f.scheduleTarget.value,cooldownMinutes:Number(f.scheduleCooldown.value),quietHours:{enabled:f.scheduleQuiet.checked,start:f.scheduleQuietStart.value,end:f.scheduleQuietEnd.value},...(project?{timeZone:f.scheduleZone.value.trim(),resumeInactive:f.scheduleResume.checked}:{})};
}
export function projectScheduleHTML(data){return `<div class="settings-section-intro"><div><h3>A shared schedule for your team</h3><p>Calendar dates, deadline alerts and optional agent check-ins stay together.</p></div></div><form id="pack-project-schedule" class="project-resource-form">${reminderFields(data.schedule,{project:true})}<p class="schedule-note">Reminders continue while HeloScrum’s backend is running. Sleep or downtime pauses them; missed reminders are grouped when it returns. Closing your browser is fine.</p><footer class="project-resource-actions"><span>Defaults for this project. Plans can override reminder rules.</span><button class="primary" type="submit">Save reminder settings</button></footer></form>`;}
export function scheduleDialog(board){
  const p=board.detail;
  board.dialogShell('Plan schedule & reminders',`<form class="work-item-form" id="pack-work-schedule">${dateFields(p.schedule,p.reminders.timeZone)}${reminderFields(p.reminders,{inherit:true,overrides:p.schedule?.overrides})}<label>Reason / context <small>optional</small><textarea name="note" rows="2" maxlength="4000" placeholder="Explain a deadline change for the team"></textarea></label><footer>${button('close','Cancel')}<button type="submit" class="primary">Save schedule</button></footer></form>`);
  const form=board.dialog.querySelector('form');form.addEventListener('submit',e=>{e.preventDefault();e.stopPropagation();board.working(async()=>{const schedule={...readDates(form),overrides:readReminders(form)};await board.api('work/schedule',{project:board.project.path,planId:p.id,expectedRevision:p.revision,schedule,note:form.elements.note.value});board.closeDialog();board.toast('Schedule saved',null,{tone:'success'});await board.refresh(true);}).catch(error=>board.error(error));});
}
export function briefScheduleFields(board){const settings=board.data.calendar.settings;return `<div class="work-form-section"><div class="work-step"><span>${libraryIcon('calendar',18)}</span><div><h3>Set the pace <small>optional</small></h3><p>Add dates now, or later from the task board. Reminders begin when work is submitted.</p></div></div>${dateFields(board.draft.schedule,settings.timeZone)}${reminderFields(settings,{inherit:true,overrides:board.draft.schedule?.overrides})}</div>`;}
export function scheduleStrip(p){return `<div class="work-schedule-strip">${libraryIcon('calendar',16)}<span>${p.schedule?.due?'Due '+esc(p.schedule.due.replace('T',' · ')):'No plan deadline'}<small>${esc(p.reminders.timeZone)} · ${p.schedule?.overrides?'Custom reminders':'Project reminders'}</small></span>${['draft','active'].includes(p.status)?button('schedule','Dates & reminders'):''}</div>`;}
export function scheduleNav(board){return `<nav class="schedule-nav" aria-label="Project work views">${[['board','Tasks','list-checks'],['calendar','Calendar','calendar'],['reminders','Reminders','bell']].map(([id,label,icon])=>button('schedule-view',libraryIcon(icon,16)+' '+label+(id==='reminders'&&board.data.calendar?.unread?` <span>${board.data.calendar.unread}</span>`:''),`data-id="${id}" aria-pressed="${(board.view||'board')===id}"`)).join('')}<span class="schedule-zone">${esc(board.data.calendar?.timeZone||'')}</span></nav>`;}
export function calendarHTML(board){
  const data=board.data.calendar,today=todayIn(data.timeZone);board.calendarMonth||=today.slice(0,7);board.calendarDay||=today;
  const month=new Date(board.calendarMonth+'-01T12:00:00Z'),first=new Date(month);first.setUTCDate(1-((first.getUTCDay()+6)%7));
  const entries=data.entries.filter(e=>e.planStatus!=='archived'&&(e.startDate||e.dueDate));
  const onDay=day=>entries.filter(e=>e.dueDate===day||e.startDate===day||e.kind==='sprint'&&e.startDate<=day&&e.dueDate>=day);
  const agenda=onDay(board.calendarDay).sort((a,b)=>(a.dueAt||a.startAt)-(b.dueAt||b.startAt));
  return `<section class="schedule-calendar" aria-label="Project calendar"><header><div><span class="eyebrow">ONE SCHEDULE FOR YOU AND YOUR AGENTS</span><h2>${month.toLocaleDateString([],{timeZone:'UTC',month:'long',year:'numeric'})}</h2></div><div>${button('calendar-month',libraryIcon('chevron-left',18),'data-id="-1" aria-label="Previous month"')}${button('calendar-today','Today')}${button('calendar-month',libraryIcon('chevron-right',18),'data-id="1" aria-label="Next month"')}</div></header><div class="calendar-key"><span>${libraryIcon('clipboard-list',13)} Task</span><span>${libraryIcon('flag',13)} Milestone</span><span>${libraryIcon('rotate-ccw',13)} Sprint window</span><span class="is-overdue">${libraryIcon('circle-alert',13)} Overdue</span></div><div class="calendar-grid" role="group" aria-label="${esc(board.calendarMonth)} dates">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(day=>`<span class="calendar-weekday">${day}</span>`).join('')}${Array.from({length:Math.ceil((((month.getUTCDay()+6)%7)+new Date(Date.UTC(month.getUTCFullYear(),month.getUTCMonth()+1,0)).getUTCDate())/7)*7},(_,i)=>{const date=new Date(first);date.setUTCDate(first.getUTCDate()+i);const key=dateKey(date),items=onDay(key);return `<div class="calendar-cell ${key.slice(0,7)!==board.calendarMonth?'outside-month':''} ${key===board.calendarDay?'selected-day':''}">${button('calendar-day',`<time datetime="${key}">${date.getUTCDate()}</time>${key===today?'<span>Today</span>':''}`,`data-id="${key}" aria-label="${key}${items.length?', '+items.length+' scheduled items':''}" aria-pressed="${key===board.calendarDay}" ${key===today?'aria-current="date"':''}`)}${items.slice(0,2).map(e=>button('calendar-entry',`${libraryIcon(iconFor(e.schedule?.milestone?'milestone':e.kind),12)}<span>${esc(e.title)}</span>`,`class="calendar-event ${e.overdue?'is-overdue':''} kind-${e.schedule?.milestone?'milestone':e.kind}" data-id="${esc(e.id)}" title="${esc(e.title)} · ${esc(e.planTitle)}"`)).join('')}${items.length>2?button('calendar-day',`+${items.length-2} more`,`class="calendar-more" data-id="${key}"`):''}</div>`;}).join('')}</div><section class="calendar-agenda"><h3>${dateLabel(board.calendarDay)} <span>${agenda.length} scheduled item${agenda.length===1?'':'s'}</span></h3>${agenda.map(e=>button('calendar-entry',`${libraryIcon(iconFor(e.schedule?.milestone?'milestone':e.kind),20)}<span><strong>${esc(e.title)}</strong><small>${esc(e.planTitle)} · ${esc(e.kind)}${e.planStatus==='draft'?' · Draft':''}</small></span><span>${e.overdue?'Overdue':e.dueDate===board.calendarDay?'Deadline':e.startDate===board.calendarDay?'Starts':'In sprint'}<small>${e.dueAt!=null?'Due '+dateLabel(e.dueDate):''}</small></span>`,`class="calendar-agenda-item ${e.overdue?'is-overdue':''}" data-id="${esc(e.id)}"`)).join('')||'<p>No dates here yet. Add a deadline from a task, plan, or sprint.</p>'}</section><p class="schedule-note">${entries.length} dated items · ${data.entries.filter(e=>e.planStatus==='active'&&e.overdue).length} overdue · ${esc(data.timeZone)}</p></section>`;
}
export function remindersHTML(board){
  const data=board.data.calendar;
  return `<section class="schedule-reminders"><header><div><span class="eyebrow">SAVED, EVEN WHEN YOU ARE AWAY</span><h2>Reminders</h2><p>Deadline alerts and agent delivery receipts, kept with the plan.</p></div><div>${data.unread?button('reminder-read-all','Mark all read'):''}${button('reminder-settings',libraryIcon('settings-2',16)+' Project defaults')}</div></header>${data.lastError?`<p class="schedule-warning" role="status">The reminder worker needs attention: ${esc(data.lastError)}</p>`:''}<p class="schedule-worker-state">${libraryIcon('clock',14)} ${data.settings.enabled?'Reminders enabled':'Project reminders paused · plan overrides may still be enabled'} · ${data.lastTickAt?'Last checked '+new Date(data.lastTickAt).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'}):'Waiting for the first check'} · ${esc(data.timeZone)}</p>${data.total>100?'<p class="schedule-note">Showing the latest 100 reminders. Earlier delivery history stays attached to each plan.</p>':''}${(data.notices||[]).map(n=>`<article class="schedule-notice ${n.readAt||n.obsolete?'is-read':''}"><header><span class="schedule-notice-icon">${libraryIcon(n.obsolete?'circle-check':n.summary.includes('Overdue')?'circle-alert':'bell',21)}</span><div><strong>${esc(n.title)}</strong><small>${new Date(n.at).toLocaleString()}${n.obsolete?' · No longer actionable':n.readAt?' · Read':' · Unread'}</small></div></header><p>${esc(n.summary)}</p>${n.deliveryNote?`<p class="schedule-note">${esc(n.deliveryNote)}</p>`:''}${!n.deliveries.length&&!n.deliveryNote?'<p class="schedule-note">Saved for you · No agents contacted</p>':''}${n.deliveries.map(d=>`<div class="schedule-receipt"><span>${board.owner(d.to)}<strong>${esc(({queued:'Queued',pending:'Preparing',delivered:'Delivered',uncertain:'Needs Review',cancelled:'Cancelled',failed:'Queue failed',delivering:'Delivering'})[d.status]||d.status)}</strong></span><p>${esc(d.error||d.waiting||'')}${d.status==='uncertain'?' Inspect the agent session before sending another message. This check-in will not be replayed automatically.':''}</p>${d.resume?`<small>${d.resume.state==='requested'?'Session resume requested':d.resume.state==='attempted'?'Resume outcome needs review':esc(d.resume.error||d.resume.state)}</small>`:''}${d.retryable?button('reminder-retry','Retry queue',`data-id="${n.id}" data-event="${d.eventId}"`):''}</div>`).join('')}<footer>${button('reminder-plan','Open plan →',`data-id="${n.planId}"`)}${!n.readAt?button('reminder-read','Mark read',`data-id="${n.id}"`):''}</footer></article>`).join('')||`<div class="schedule-empty">${libraryIcon('bell',32)}<h3>You’re caught up.</h3><p>Set a task or plan deadline to receive an alert here. Agent check-ins are optional.</p>${button('schedule-view','View calendar','data-id="calendar"')}</div>`}</section>`;
}
export async function scheduleAction(board,b){
  const action=b.dataset.work,id=b.dataset.id;
  if(action==='schedule-view'){board.view=id;board.render();return true;}
  if(action==='schedule'){scheduleDialog(board);return true;}
  if(action==='calendar-month'){const date=new Date(board.calendarMonth+'-01T12:00:00Z');date.setUTCMonth(date.getUTCMonth()+Number(id));board.calendarMonth=dateKey(date).slice(0,7);board.render();return true;}
  if(action==='calendar-today'){board.calendarDay=todayIn(board.data.calendar.timeZone);board.calendarMonth=board.calendarDay.slice(0,7);board.render();return true;}
  if(action==='calendar-day'){board.calendarDay=id;board.render();return true;}
  if(action==='calendar-entry'){const entry=board.data.calendar.entries.find(e=>e.id===id);if(!entry)return true;board.view='board';board.section=entry.kind==='sprint'?'delivery':'tasks';await board.open(entry.planId);if(['task','milestone'].includes(entry.kind))board.editItem(entry.entityId);else if(entry.kind==='plan'&&['draft','active'].includes(board.detail.status))scheduleDialog(board);return true;}
  if(action==='reminder-settings'){board.onScheduleSettings?.();return true;}
  if(action==='reminder-plan'){board.view='board';await board.open(id);return true;}
  if(action==='reminder-read-all'){await board.working(async()=>{await board.api('work/reminder',{project:board.project.path,action:'read-all'});await board.refresh(true);});return true;}
  if(['reminder-read','reminder-retry'].includes(action)){await board.working(async()=>{await board.api('work/reminder',{project:board.project.path,id,eventId:b.dataset.event,action:action==='reminder-read'?'read':'retry'});await board.refresh(true);});return true;}
  return false;
}
